// v0.6.0's list additions for media and mentions: media lenses, sort and total, and mention search
// and the one-post filter, each echoed so a caller can tell a site that did them from one that did not.

import { describe, expect, it, vi } from "vitest";
import { createSiteClient } from "../src/client.js";
import { memoryAdapter, type MemoryAdapterOptions } from "../src/testing.js";
import { KEY, ORIGIN, req, site } from "./helpers.js";

const PNG = new Uint8Array([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0, 0, 0, 0]);

function client(options: MemoryAdapterOptions = {}) {
  const adapter = memoryAdapter(options);
  const s = site(adapter);
  return { adapter, api: s.api, client: createSiteClient({ baseUrl: ORIGIN, key: KEY, fetch: s.fetch }) };
}

describe("media lenses and sort (v0.6.0)", () => {
  it("answers each lens with the files it names, the total across pages, and the order it applied", async () => {
    const { adapter, client: c } = client();
    const used = await c.media.upload({ bytes: PNG, contentType: "image/png", filename: "used.png", alt: "In a post", changeId: "u1" });
    const bare = await c.media.upload({ bytes: PNG, contentType: "image/png", filename: "bare.png", changeId: "u2" });
    await c.saveDraft("p", { source: `# P\n![x](/media/${used.id})\n`, expectedVersion: null, changeId: "c1" });
    adapter.mediaStore.get(used.id)!.item.bytes = 2 * 1024 * 1024;
    expect((await c.media.list({ lens: "unattached" })).items.map((i) => i.id)).toEqual([bare.id]);
    expect((await c.media.list({ lens: "no-alt" })).items.map((i) => i.id)).toEqual([bare.id]);
    expect((await c.media.list({ lens: "large" })).items.map((i) => i.id)).toEqual([used.id]);
    const bySize = await c.media.list({ sort: "size", limit: 1 });
    expect(bySize).toMatchObject({ items: [{ id: used.id }], total: 2, sorted: { sort: "size", dir: "desc" } });
    expect((await c.media.list({ sort: "name", dir: "desc" })).items.map((i) => i.filename)).toEqual(["used.png", "bare.png"]);
    expect((await c.meta()).capabilities.mediaLenses).toEqual(["unattached", "no-alt", "large"]);
  });

  it("PLANT: answers a lens the site does not name with 501, and an unknown lens or sort with 400, before the adapter", async () => {
    const { adapter, api } = client({ mediaLenses: false });
    const spy = vi.spyOn(adapter.media!, "list");
    expect((await api.handle(req("/api/carrel/v1/media?lens=no-alt"))).status).toBe(501);
    for (const q of ["lens=pretty", "sort=colour", "dir=up"]) expect((await api.handle(req(`/api/carrel/v1/media?${q}`))).status, q).toBe(400);
    expect(spy).not.toHaveBeenCalled();
    expect((await api.handle(req("/api/carrel/v1/media"))).status).toBe(200);
  });
});

describe("mention search and the one-post filter (v0.6.0)", () => {
  it("filters by words and by post, keeps the whole queue's counts, and echoes what it applied", async () => {
    const { adapter, client: c } = client();
    adapter.receiveMention({ sourceUrl: "https://a.example/1", targetId: "post-a", authorName: "Ada" });
    adapter.receiveMention({ sourceUrl: "https://b.example/2", targetId: "post-b", excerpt: "ada wrote this" });
    adapter.receiveMention({ sourceUrl: "https://c.example/3", targetId: "post-a" });
    const byWord = await c.mentions.list({ q: "ADA" });
    expect(byWord.items.map((m) => m.sourceUrl)).toEqual(["https://b.example/2", "https://a.example/1"]);
    expect(byWord.filtered).toEqual({ q: "ADA" });
    expect(byWord.counts.pending).toBe(3);
    const byPost = await c.mentions.list({ targetId: "post-a", q: "ada" });
    expect(byPost.items.map((m) => m.sourceUrl)).toEqual(["https://a.example/1"]);
    expect(byPost.filtered).toEqual({ q: "ada", targetId: "post-a" });
    expect((await c.mentions.list()).filtered).toBeUndefined();
  });

  it("PLANT: refuses a search too long or an empty post id before the adapter", async () => {
    const { adapter, api } = client();
    const spy = vi.spyOn(adapter.mentions!, "list");
    for (const q of [`q=${"x".repeat(201)}`, "targetId="]) expect((await api.handle(req(`/api/carrel/v1/mentions?${q}`))).status, q).toBe(400);
    expect(spy).not.toHaveBeenCalled();
  });
});

test/planted.test.ts.source:
// The job's plants: each is a request that must be refused, and each assertion also checks that the
// adapter never ran, so a refusal cannot come from the site's own code by accident.

import { describe, expect, it, vi } from "vitest";
import { memoryAdapter } from "../src/testing.js";
import { KEY, body, req, site } from "./helpers.js";

function spied() {
  const adapter = memoryAdapter();
  const calls = vi.fn();
  for (const [name, fn] of Object.entries(adapter.content)) {
    (adapter.content as unknown as Record<string, unknown>)[name] = (...args: unknown[]) => {
      calls(name);
      return (fn as (...a: unknown[]) => unknown)(...args);
    };
  }
  return { adapter, calls };
}

describe("PLANT: the key off its prefix", () => {
  const paths = [
    "/api/carrel/v2/meta",
    "/api/carrel/v1x/meta",
    "/api/carrel/meta",
    "/admin/posts",
    "/api/carrel/v1/../../admin/posts",
    "/api/carrel/v1/%2e%2e/%2e%2e/admin",
  ];

  for (const path of paths) {
    it(`is not served at ${path}`, async () => {
      const { adapter, calls } = spied();
      const { api } = site(adapter);
      const request = req(path);
      expect(api.matches(request)).toBe(false);
      const response = await api.handle(request);
      expect(response.status).toBe(404);
      expect(calls).not.toHaveBeenCalled();
    });
  }
});

describe("PLANT: the wrong key", () => {
  const cases: Array<[string, string | null, Record<string, string>?]> = [
    ["no header", null],
    ["a different key", "z".repeat(KEY.length)],
    ["the key with one character more", `${KEY}x`],
    ["the key with one character less", KEY.slice(0, -1)],
    ["an empty bearer", ""],
    ["the key under another scheme", null, { authorization: `Basic ${KEY}` }],
  ];

  for (const [name, key, headers] of cases) {
    it(`refuses ${name}`, async () => {
      const { adapter, calls } = spied();
      const { api, logs } = site(adapter);
      const response = await api.handle(req("/api/carrel/v1/content", { key, headers }));
      expect(response.status).toBe(401);
      expect(await response.json()).toEqual({ error: "unauthorized", message: "Unauthorized." });
      expect(calls).not.toHaveBeenCalled();
      expect(logs).toContainEqual(expect.objectContaining({ siteApi: "refused" }));
    });
  }

  it("refuses every request, even the right one, while the site's key is unset or short", async () => {
    for (const key of [undefined, "", "short-key"]) {
      const { api } = site(memoryAdapter(), { key });
      const response = await api.handle(req("/api/carrel/v1/meta", { key: key ?? "" }));
      expect(response.status).toBe(503);
    }
  });
});

describe("PLANT: a stale expectedVersion", () => {
  async function seeded() {
    const s = site();
    const created = await s.api.handle(
      req("/api/carrel/v1/content/first-post/draft", {
        method: "PUT",
        ...body({ source: "# First\n", expectedVersion: null, changeId: "c1" }),
      }),
    );
    expect(created.status).toBe(200);
    const { version } = await created.json();
    return { ...s, version: version as string };
  }

  it("refuses a draft save against a version the site no longer holds", async () => {
    const { api, version } = await seeded();
    await api.handle(
      req("/api/carrel/v1/content/first-post/draft", {
        method: "PUT",
        ...body({ source: "# First, again\n", expectedVersion: version, changeId: "c2" }),
      }),
    );
    const stale = await api.handle(
      req("/api/carrel/v1/content/first-post/draft", {
        method: "PUT",
        ...body({ source: "# Overwrite\n", expectedVersion: version, changeId: "c3" }),
      }),
    );
    expect(stale.status).toBe(409);
    const refusal = await stale.json();
    expect(refusal.error).toBe("version-conflict");
    expect(refusal.currentVersion).not.toBe(version);
  });

  it("refuses publish, schedule and unpublish on a stale version, and changes nothing", async () => {
    const { api, adapter } = await seeded();
    const before = structuredClone(adapter.store.get("first-post"));
    const writes: Array<[string, Record<string, unknown>]> = [
      ["publish", {}],
      ["schedule", { publishAt: "2030-01-01T00:00:00Z" }],
      ["unpublish", {}],
    ];
    for (const [action, extra] of writes) {
      const response = await api.handle(
        req(`/api/carrel/v1/content/first-post/${action}`, {
          method: "POST",
          ...body({ expectedVersion: "stale", changeId: "c9", ...extra }),
        }),
      );
      expect(response.status, action).toBe(409);
    }
    expect(adapter.store.get("first-post")).toEqual(before);
  });

  it("refuses a create over an id that exists, and a non-null version for an id that does not", async () => {
    const { api } = await seeded();
    const create = await api.handle(
      req("/api/carrel/v1/content/first-post/draft", {
        method: "PUT",
        ...body({ source: "# Clobber\n", expectedVersion: null, changeId: "c4" }),
      }),
    );
    expect(create.status).toBe(409);
    const ghost = await api.handle(
      req("/api/carrel/v1/content/no-such-post/draft", {
        method: "PUT",
        ...body({ source: "# Ghost\n", expectedVersion: "v1", changeId: "c5" }),
      }),
    );
    expect(ghost.status).toBe(409);
    expect((await ghost.json()).currentVersion).toBeNull();
  });

  it("refuses a write with no expectedVersion or no change id before the site sees it", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter);
    for (const payload of [
      { source: "# x\n", changeId: "c1" },
      { source: "# x\n", expectedVersion: null },
      { source: "# x\n", expectedVersion: null, changeId: "has spaces" },
    ]) {
      const response = await api.handle(
        req("/api/carrel/v1/content/x/draft", { method: "PUT", ...body(payload) }),
      );
      expect(response.status).toBe(400);
    }
    expect(calls).not.toHaveBeenCalled();
  });
});

describe("PLANT: an unknown route", () => {
  it("refuses a path inside the prefix that the contract does not name", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter);
    for (const path of ["/api/carrel/v1", "/api/carrel/v1/", "/api/carrel/v1/nope", "/api/carrel/v1/content/a/b/c"]) {
      const response = await api.handle(req(path));
      expect(response.status, path).toBe(404);
      expect((await response.json()).error).toBe("not-found");
    }
    expect(calls).not.toHaveBeenCalled();
  });

  it("refuses a known path with the wrong method", async () => {
    const { api } = site();
    const response = await api.handle(req("/api/carrel/v1/content/a", { method: "PATCH" }));
    expect(response.status).toBe(405);
  });

  it("answers 501 for the groups declared for later stages, and for media on a site without it", async () => {
    const { api: noMedia } = site(memoryAdapter({ media: false }));
    for (const path of ["media", "media/anything"]) {
      expect((await noMedia.handle(req(`/api/carrel/v1/${path}`))).status, path).toBe(501);
    }
    const { api } = site();
    for (const group of ["inbox", "insight", "publications"]) {
      const response = await api.handle(req(`/api/carrel/v1/${group}/anything`));
      expect(response.status, group).toBe(501);
    }
  });

  it("does not tell a caller without the key which routes exist", async () => {
    const { api } = site();
    const known = await api.handle(req("/api/carrel/v1/meta", { key: null }));
    const unknown = await api.handle(req("/api/carrel/v1/nope", { key: null }));
    expect(known.status).toBe(401);
    expect(unknown.status).toBe(401);
  });

  it("refuses an id that could be a path", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter);
    const response = await api.handle(req("/api/carrel/v1/content/..%2Fsecrets"));
    expect(response.status).toBe(400);
    expect(calls).not.toHaveBeenCalled();
  });
});

describe("rate limit", () => {
  it("refuses before the key is checked when the limiter says no", async () => {
    const { adapter, calls } = spied();
    const { api } = site(adapter, { limiter: { limit: async () => ({ success: false }) } });
    const response = await api.handle(req("/api/carrel/v1/content"));
    expect(response.status).toBe(429);
    expect(calls).not.toHaveBeenCalled();
  });

  it("fails closed when the limiter throws", async () => {
    const { api } = site(memoryAdapter(), {
      limiter: {
        limit: async () => {
          throw new Error("binding missing");
        },
      },
    });
    expect((await api.handle(req("/api/carrel/v1/meta"))).status).toBe(503);
  });

  it("limits by the caller's address", async () => {
    const keys: string[] = [];
    const { api } = site(memoryAdapter(), {
      limiter: {
        limit: async ({ key }) => {
          keys.push(key);
          return { success: true };
        },
      },
    });
    await api.handle(req("/api/carrel/v1/meta", { headers: { "cf-connecting-ip": "203.0.113.9" } }));
    expect(keys).toEqual(["203.0.113.9"]);
  });
});

describe("a site that answers outside the contract", () => {
  it("is reported as a site failure, and the malformed body is not passed on", async () => {
    const adapter = memoryAdapter();
    adapter.content.list = async () => ({ items: [{ id: "x" }], nextCursor: null }) as never;
    const { api, logs } = site(adapter);
    const response = await api.handle(req("/api/carrel/v1/content"));
    expect(response.status).toBe(500);
    expect(JSON.stringify(await response.json())).not.toContain('"id":"x"');
    expect(logs).toContainEqual(expect.objectContaining({ siteApi: "contract-breach" }));
  });
});

test/contract-v0.5.0.test.ts.source:
// PLANT: the v0.5.0 contract, unchanged but for what v0.6.0 names. v0.6.0 is additive: every v0.5.0
// route and body stays as it was, so a site or a Carrel on v0.5.0 keeps working.
//
// test/fixtures/contract-v0.5.0.json was written from the v0.5.0 build (tag v0.5.0, 79f0a8f, which
// carries PACKAGE_VERSION 0.5.0): each exported schema as JSON Schema, the route table and the schema hash.

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { z } from "zod";
import * as contract from "../src/contract.js";
import { additiveOnly, added, now, type JsonSchema } from "./additive.js";

const V050 = JSON.parse(readFileSync(new URL("./fixtures/contract-v0.5.0.json", import.meta.url), "utf8")) as {
  version: string;
  schemaHash: string;
  routes: Array<Record<string, string>>;
  schemas: Record<string, JsonSchema>;
};

/** Every v0.5.0 schema v0.6.0 extends, and exactly the optional properties it adds to each. */
const ADDED: Record<string, string[]> = {
  Capabilities: ["contentTags", "mediaLenses", "mentionReset"],
  Meta: [],
  ContentSummary: ["tags", "version"],
  ContentDoc: ["tags"],
  ListQuery: ["dir", "sort"],
  ContentList: ["sorted", "total"],
  MediaListQuery: ["dir", "lens", "sort"],
  MediaList: ["sorted", "total"],
  MentionListQuery: ["q", "targetId"],
  MentionList: ["filtered"],
};

/** The one v0.5.0 schema v0.6.0 widens rather than extends: a decision may also be reset. */
const WIDENED = "MentionDecideInput";

const exported = Object.entries(contract)
  .filter(([, value]) => value instanceof z.ZodType)
  .map(([name]) => name);

describe("the v0.5.0 contract", () => {
  it("is the recorded v0.5.0", () => {
    expect(V050.version).toBe("0.5.0");
    expect(V050.schemaHash).toBe("ec6a11c73e583361280e77801084b0c566f815a2e9675e21c1d9d622084db86c");
    expect(V050.routes.length).toBe(29);
  });

  it("keeps every v0.5.0 route exactly, and adds only the content tags route", () => {
    for (const route of V050.routes) expect(contract.ROUTES, JSON.stringify(route)).toContainEqual(route);
    const fresh = contract.ROUTES.filter((r) => !V050.routes.some((old) => JSON.stringify(old) === JSON.stringify(r)));
    expect(fresh.map((r) => `${r.method} ${r.path}`)).toEqual(["PUT /content/:id/tags"]);
  });

  for (const name of Object.keys(V050.schemas).filter((n) => !(n in ADDED) && n !== WIDENED)) {
    it(`keeps ${name} identical`, () => {
      expect(now(name)).toEqual(V050.schemas[name]);
    });
  }

  for (const [name, props] of Object.entries(ADDED)) {
    it(`extends ${name} by optional properties only: ${props.join(", ") || "none of its own"}`, () => {
      additiveOnly(V050.schemas[name]!, now(name), name);
      expect(added(V050.schemas[name]!, now(name)).sort()).toEqual(props);
    });
  }

  it("widens the mention decision by reset, and nothing else", () => {
    const before = V050.schemas[WIDENED]!;
    const after = now(WIDENED);
    const decision = (s: JsonSchema) => (s.properties!.decision as { enum: string[] }).enum;
    expect(decision(after)).toEqual([...decision(before), "reset"]);
    const strip = (s: JsonSchema) => ({ ...s, properties: { ...s.properties, decision: undefined } });
    expect(strip(after)).toEqual(strip(before));
  });

  it("adds only the new schemas v0.6.0 names", () => {
    expect(exported.filter((n) => !(n in V050.schemas)).sort()).toEqual(["ContentTag", "ContentTagsInput", "ContentTags", "MediaLens", "SortDir"].sort());
  });

  it("parses v0.5.0 bodies with the v0.6.0 schemas", () => {
    const meta = {
      api: "carrel-site-api",
      packageVersion: "0.5.0",
      schemaHash: V050.schemaHash,
      site: { id: "memory", name: "Memory", origin: "https://memory.example" },
      capabilities: { content: true, preview: true, media: false, inbox: false, insight: false, publications: false, mentions: true },
    };
    expect(contract.Meta.safeParse(meta).success).toBe(true);
    const row = { id: "a", kind: "post", title: "A", status: "draft", path: null, publishAt: null, publishedAt: null, updatedAt: null };
    expect(contract.ContentList.safeParse({ items: [row], nextCursor: null }).success).toBe(true);
    expect(contract.MediaList.safeParse({ items: [], nextCursor: null }).success).toBe(true);
    const counts = { unverified: 0, pending: 0, approved: 0, rejected: 0, failed: 0 };
    expect(contract.MentionList.safeParse({ items: [], nextCursor: null, counts, expiring: { failed: 0, rejected: 0 } }).success).toBe(true);
    expect(contract.MentionDecideInput.safeParse({ decision: "approve", expectedVersion: "m1", changeId: "c1" }).success).toBe(true);
  });

  it("changes the schema hash on purpose, and moves the package version to 0.6.0", async () => {
    expect(await contract.schemaHash()).not.toBe(V050.schemaHash);
    expect(contract.PACKAGE_VERSION).toBe("0.6.0");
  });
});

